#include <iostream>
using namespace std;

int main() {
    long long a, b, c;
    if(!(cin >> a >> b >> c)) return 0;

    long long sum = a + b + c;
    if (sum % 2 != 0) {
        cout << "Impossible" << endl;
        return 0;
    }

    long long x = (a + b - c) / 2;
    long long y = (b + c - a) / 2;
    long long z = (c + a - b) / 2;

    if (x >= 0 && y >= 0 && z >= 0) {
        cout << x << " " << y << " " << z << endl;
    } else {
        cout << "Impossible" << endl;
    }

    return 0;
}
